-- GENERATED by tools/sync_server_rules.py from main/data/outposts.lua - edit that file, not this copy.
-- The outpost roster (plan.md §2.9) - the stations each faction docks at,
-- respawns at and defends. Laid out like main/data/ships.lua (per direct
-- instruction): both factions' outposts share ONE chassis - every stat in
-- `data` is the same for The Accord and The Swarm - and only the look
-- differs, in a small `faction_skins` table. One entry with per-faction
-- skins, never two copied entries, for the same stat-drift reason ships.lua's
-- header gives.
--
-- WHERE an outpost stands is not here: that is map geography and stays in
-- main/data/star_systems.lua (has_outpost / OUTPOST_DENIED / outpost_position
-- / spawn_points / OUTPOST_CORNER_INSET).
--
-- Models: main/main.collection places one accord_outpost / swarm_outpost game
-- object pair (each a fixed dock plus a spinning rotor child carrying 8 ad
-- panels - tools/setup_station_exteriors.py builds them), and moves/hides it
-- per system. A collection can't read its model paths from Lua, so the
-- collection names the same .model files listed under `faction_skins` below;
-- tests/outposts_data_harness.lua fails if the two ever disagree.
--
-- This file is also copied to the server (tools/sync_server_rules.py) -
-- nakama-server/modules/outposts.lua reads the hull and the destroyed time
-- from it - so it must stay plain Lua with no engine calls.

local M = {}

-- Faction order used wherever every outpost in a system is walked.
M.FACTIONS = { "accord", "swarm" }

-- The regular outpost. Which tier stands in a system - regular, upgraded
-- or fortified - follows its control level (M.CONTROL_LEVELS below, plan.md
-- §2.7 "Outpost progression"); main/outpost_rules.lua applies it.
M.DEFAULT = "outpost"

M.OUTPOSTS = {
	["outpost"] = {
		-- Shared chassis: identical for both factions.
		data = {
			-- Hull: BSGO wiki's Outposts page - a regular outpost has 50,000
			-- hull points; a destroyed one is gone for 60 minutes, then returns
			-- at full hull (server: nakama-server/modules/outposts.lua).
			hull_points = 50000,
			destroyed_for_sec = 60 * 60,

			-- Rough size, for clicking and the target marker (m).
			radius_m = 150,

			-- Docking (per direct instruction): a ship may dock within
			-- dock_range_m of its own faction's outpost; holding there for
			-- dock_countdown_sec completes it. Launching (and arriving from a
			-- jump) puts the ship launch_distance_m out - beyond dock range,
			-- so a fresh arrival has to fly in before it can dock.
			dock_range_m = 1000,
			dock_countdown_sec = 5,
			launch_distance_m = 1200,

			-- Number of ad panels on the rotor (main/station_ads.lua).
			ad_panels = 8,

			-- Where the defences stand (main/outpost_rules.lua): the sentry
			-- platforms evenly spaced on a horizontal ring this far from the
			-- outpost, the jump beacon this far from it towards the system
			-- centre. Ours (BSGO gives no distances) - clear of the station's
			-- own ~400 m bulk and inside the 1,200 m launch distance.
			platform_ring_m = 900,
			beacon_offset_m = 1100,

			-- Reference only, not used yet (BSGO wiki, Outposts): the outpost's
			-- own power pool and sight, and the longer dock while in combat
			-- (Update 47: 10 s when in combat or "threat").
			power = 4500,
			visual_range_m = 1300,
			dock_countdown_in_combat_sec = 10,
		},
		-- Per-faction look only. `model` is the fixed dock, `rotor_model` the
		-- spinning ring; `rotor_period_sec` is one full turn of the ring.
		faction_skins = {
			accord = {
				name = "Accord outpost",
				model = "/assets/models/outposts/accord_outpost.model",
				rotor_model = "/assets/models/stations/accord/rotor.model",
				rotor_period_sec = 110,
			},
			swarm = {
				name = "Swarm outpost",
				model = "/assets/models/outposts/swarm_outpost.model",
				rotor_model = "/assets/models/stations/swarm/rotor.model",
				rotor_period_sec = 120,
			},
		},
	},

	-- Upgraded / fortified tiers (BSGO Update 34, March 2014): "as the
	-- outpost changes level, only the outpost's hull points change" - so each
	-- tier lists ONLY what differs; every other stat and both faction skins
	-- fall back to the regular "outpost" entry above (M.stat / M.skin), the
	-- same fallback ships.lua's `advanced` tier uses. Give a tier its own
	-- `faction_skins` once it has its own models.
	["upgraded_outpost"] = {
		data = { hull_points = 55000 },
	},
	["fortified_outpost"] = {
		data = { hull_points = 60000 },
	},
}

-- The FTL jump beacon that stands by an outpost from control level 3. Same
-- shared-chassis + faction_skins layout. BSGO publishes no beacon hull, so
-- hull_points is OURS (a placeholder to tune); the hour it stays down once
-- destroyed is BSGO Nova's.
M.BEACON = {
	data = {
		hull_points = 10000,
		destroyed_for_sec = 60 * 60,
		radius_m = 40,
	},
	faction_skins = {
		accord = { name = "Accord jump beacon", model = "/assets/models/outpost_defences/accord/beacon.model" },
		swarm  = { name = "Swarm jump beacon",  model = "/assets/models/outpost_defences/swarm/beacon.model" },
	},
}

-- Outpost progression (plan.md §2.7 "Outpost progression"; applied by
-- main/outpost_rules.lua, run by nakama-server/modules/system_match.lua).
-- BSGO's per-system, per-faction "Outpost Progress" meter (0-300 %) and the
-- 10 control levels it unlocks (bsgo.fandom.com/wiki/Outposts, 2017). `outpost` is the M.OUTPOSTS tier
-- present at that level (nil = none), `beacon` whether the FTL jump beacon is
-- up, `platforms` the sentry platforms around it by class
-- (main/data/sentry_platforms.lua) - at most 4.
M.CONTROL_LEVELS = {
	{ level = 1,  progress_pct = 50,  outpost = nil,                 beacon = false, platforms = {} }, -- system "captured"
	{ level = 2,  progress_pct = 90,  outpost = "outpost",           beacon = false, platforms = {} },
	{ level = 3,  progress_pct = 125, outpost = "outpost",           beacon = true,  platforms = { light = 2 } },
	{ level = 4,  progress_pct = 175, outpost = "outpost",           beacon = true,  platforms = { light = 4 } },
	{ level = 5,  progress_pct = 200, outpost = "upgraded_outpost",  beacon = true,  platforms = { light = 2, medium = 2 } },
	{ level = 6,  progress_pct = 225, outpost = "upgraded_outpost",  beacon = true,  platforms = { medium = 4 } },
	{ level = 7,  progress_pct = 250, outpost = "upgraded_outpost",  beacon = true,  platforms = { medium = 2, heavy = 2 } },
	{ level = 8,  progress_pct = 275, outpost = "fortified_outpost", beacon = true,  platforms = { heavy = 4 } },
	-- Levels 9 and 10: "up to 300 %, no change" - the reference gives no
	-- separate thresholds for them, so they stay nil until we choose some.
	{ level = 9,  progress_pct = nil, outpost = "fortified_outpost", beacon = true,  platforms = { heavy = 4 } },
	{ level = 10, progress_pct = nil, outpost = "fortified_outpost", beacon = true,  platforms = { heavy = 4 } },
}

-- How the meter moves (same sources plus BSGO Nova's game-features /
-- bonus-handbook guides). BSGO never published per-action amounts or the
-- drain rate: the numbers marked OURS were chosen (per direct instruction:
-- "mining + presence") so one pilot mining steadily brings an outpost in
-- within roughly 20-30 minutes. nil = no such activity in the game yet.
M.PROGRESS = {
	max_pct = 300,
	-- Below this the outpost jumps out of the system (it is also level 2's
	-- threshold - the outpost appears and leaves at the same line).
	outpost_min_pct = 90,
	-- Raised by: mining (player or mining ship), NPC kills, player kills, a
	-- completed freighter-in-distress or drone-incursion mission, and (Nova)
	-- simply having the faction's ships present. Per-action amounts: unknown.
	gain_pct = {
		mining = 2,           -- OURS: per asteroid depleted by one of the faction's pilots
		presence_per_min = 1, -- OURS: per pilot of the faction in the system, per minute
		npc_kill = nil, player_kill = nil, rescue_mission = nil, incursion_mission = nil, -- not in the game yet
	},
	-- Lowered by: a steady auto-drain every minute (rate unknown), a FAILED
	-- freighter-in-distress mission (-15 %), and (Nova) the enemy destroying
	-- the faction's mines or completing convoy routes.
	drain_pct_per_min = 1, -- OURS
	failed_rescue_mission_pct = -15,
	-- Destroyed: the meter is replaced by a repair countdown of this length
	-- (= the chassis' destroyed_for_sec). Players can still build control
	-- meanwhile; reaching level 2+ by the end brings the outpost straight
	-- back at that level (decided, per direct instruction - an older wiki
	-- revision reset it to 0 % instead).
	repair_sec = 60 * 60,
	-- Underdog scaling (Update 47): outpost and sentry-platform hull is
	-- scaled by up to this fraction - DOWN for the faction holding more of the
	-- sector, UP for the one holding less - live, as control changes.
	underdog_hull_scale = 0.36,
}

-- Permanent outposts (decided, per direct instruction): a faction's home
-- system and the 6 nearest to it - exactly the systems where the OTHER
-- faction may never have an outpost (star_systems.OUTPOST_DENIED) - always
-- have that faction's outpost: its meter never drains below
-- PROGRESS.outpost_min_pct and the outpost itself can't be destroyed (its
-- platforms and beacon can). Everywhere else the outpost has to be earned.

-- Rewards for holding outposts (BSGO Nova bonus handbook):
-- each outpost a faction holds gives every pilot of that faction this much
-- extra XP and mining income, galaxy-wide, applied after personal bonuses.
-- Outpost kill rewards are paid in full to every participant (never split);
-- enemy pilots within kill_reward_radius_m are paid but not credited.
M.REWARDS = {
	xp_bonus_per_outpost = 0.01,
	mining_bonus_per_outpost = 0.01,
	kill_reward_radius_m = 4000,
}

-- A chassis stat of outpost type `id` (default M.DEFAULT); a tier that
-- doesn't set it falls back to the regular outpost.
function M.stat(name, id)
	local outpost = M.OUTPOSTS[id or M.DEFAULT]
	if not outpost then
		return nil
	end
	local value = outpost.data and outpost.data[name]
	if value == nil then
		value = M.OUTPOSTS[M.DEFAULT].data[name]
	end
	return value
end

-- `faction`'s skin of outpost type `id` (default M.DEFAULT), or nil; a tier
-- without its own skins uses the regular outpost's.
function M.skin(faction, id)
	local outpost = M.OUTPOSTS[id or M.DEFAULT]
	if not outpost then
		return nil
	end
	local skins = outpost.faction_skins or M.OUTPOSTS[M.DEFAULT].faction_skins
	return skins[faction]
end

return M
